import heapq

def minCostToBuyApples(n: int, prices: list[int], roads: list[list[int]]) -> list[int]:
    g_empty = [[] for _ in range(n)]
    g_apples = [[] for _ in range(n)]
    for u, v, cost, tax in roads:
        g_empty[u].append((v, cost))
        g_empty[v].append((u, cost))
        g_apples[u].append((v, cost * tax))
        g_apples[v].append((u, cost * tax))

    def dijkstra(start: int, g: list) -> list[int]:
        dist = [float('inf')] * n
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in g[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(pq, (d + w, v))
        return dist

    ans = [0] * n
    for i in range(n):
        d_emp = dijkstra(i, g_empty)
        d_app = dijkstra(i, g_apples)
        best = prices[i]
        for j in range(n):
            if d_emp[j] != float('inf') and d_app[j] != float('inf'):
                best = min(best, d_emp[j] + prices[j] + d_app[j])
        ans[i] = best
    return ans

#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    std::vector<long long> minCostToBuyApples(int n, std::vector<int>& prices, std::vector<std::vector<int>>& roads) {
        std::vector<std::vector<std::pair<int, int>>> gEmpty(n), gApples(n);
        for (const auto& r : roads) {
            int u = r[0], v = r[1], c = r[2], t = r[3];
            gEmpty[u].push_back({v, c});
            gEmpty[v].push_back({u, c});
            gApples[u].push_back({v, c * t});
            gApples[v].push_back({u, c * t});
        }

        auto dijkstra = [&](int start, const std::vector<std::vector<std::pair<int, int>>>& g) -> std::vector<long long> {
            std::vector<long long> dist(n, 1e18);
            dist[start] = 0;
            std::priority_queue<std::pair<long long, int>, std::vector<std::pair<long long, int>>, std::greater<>> pq;
            pq.push({0, start});
            while (!pq.empty()) {
                auto [d, u] = pq.top();
                pq.pop();
                if (d > dist[u]) continue;
                for (const auto& [v, w] : g[u]) {
                    if (d + w < dist[v]) {
                        dist[v] = d + w;
                        pq.push({d + w, v});
                    }
                }
            }
            return dist;
        };

        std::vector<long long> ans(n);
        for (int i = 0; i < n; ++i) {
            auto dEmp = dijkstra(i, gEmpty);
            auto dApp = dijkstra(i, gApples);
            long long best = prices[i];
            for (int j = 0; j < n; ++j) {
                if (dEmp[j] < 1e18 && dApp[j] < 1e18) {
                    best = std::min(best, dEmp[j] + prices[j] + dApp[j]);
                }
            }
            ans[i] = best;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long[] minCostToBuyApples(int n, int[] prices, int[][] roads) {
        List<List<int[]>> gEmpty = new ArrayList<>();
        List<List<int[]>> gApples = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            gEmpty.add(new ArrayList<>());
            gApples.add(new ArrayList<>());
        }
        for (int[] r : roads) {
            int u = r[0], v = r[1], c = r[2], t = r[3];
            gEmpty.get(u).add(new int[]{v, c});
            gEmpty.get(v).add(new int[]{u, c});
            gApples.get(u).add(new int[]{v, c * t});
            gApples.get(v).add(new int[]{u, c * t});
        }
        long[] ans = new long[n];
        for (int i = 0; i < n; i++) {
            long[] dEmp = dijkstra(n, i, gEmpty);
            long[] dApp = dijkstra(n, i, gApples);
            long best = prices[i];
            for (int j = 0; j < n; j++) {
                if (dEmp[j] < Long.MAX_VALUE && dApp[j] < Long.MAX_VALUE) {
                    best = Math.min(best, dEmp[j] + prices[j] + dApp[j]);
                }
            }
            ans[i] = best;
        }
        return ans;
    }

    private long[] dijkstra(int n, int start, List<List<int[]>> g) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, start});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0];
            int u = (int)top[1];
            if (d > dist[u]) continue;
            for (int[] edge : g.get(u)) {
                int v = edge[0], w = edge[1];
                if (d + w < dist[v]) {
                    dist[v] = d + w;
                    pq.offer(new long[]{d + w, v});
                }
            }
        }
        return dist;
    }
}

function minCostToBuyApples(n, prices, roads) {
    const gEmpty = Array.from({ length: n }, () => []);
    const gApples = Array.from({ length: n }, () => []);
    for (const [u, v, c, t] of roads) {
        gEmpty[u].push([v, c]);
        gEmpty[v].push([u, c]);
        gApples[u].push([v, c * t]);
        gApples[v].push([u, c * t]);
    }

    function dijkstra(start, g) {
        const dist = new Array(n).fill(Infinity);
        dist[start] = 0;
        const pq = [[0, start]];
        while (pq.length > 0) {
            pq.sort((a, b) => a[0] - b[0]);
            const [d, u] = pq.shift();
            if (d > dist[u]) continue;
            for (const [v, w] of g[u]) {
                if (d + w < dist[v]) {
                    dist[v] = d + w;
                    pq.push([d + w, v]);
                }
            }
        }
        return dist;
    }

    const ans = new Array(n);
    for (let i = 0; i < n; i++) {
        const dEmp = dijkstra(i, gEmpty);
        const dApp = dijkstra(i, gApples);
        let best = prices[i];
        for (let j = 0; j < n; j++) {
            if (dEmp[j] < Infinity && dApp[j] < Infinity) {
                best = Math.min(best, dEmp[j] + prices[j] + dApp[j]);
            }
        }
        ans[i] = best;
    }
    return ans;
}
